SELECT DISTINCT ZZ_SCRATCH_KIN.c_name_chn, ZZ_SCRATCH_KIN.c_index_year, ZZ_SCRATCH_KIN.c_kin_chn, ZZ_SCRATCH_KIN.c_kin_index_year, ZZ_SCRATCH_KIN.c_kin_rel, ENTRY_CODES.c_entry_desc, ENTRY_CODES.c_entry_desc_chn, ENTRY_DATA.c_year
FROM ZZ_SCRATCH_KIN INNER JOIN (ENTRY_CODES INNER JOIN ENTRY_DATA ON ENTRY_CODES.c_entry_code = ENTRY_DATA.c_entry_code) ON ZZ_SCRATCH_KIN.c_kin_id = ENTRY_DATA.c_personid
WHERE (((ZZ_SCRATCH_KIN.c_kin_rel) <> "ego"));

SELECT DISTINCT BIOG_MAIN.c_name_chn, POSTED_TO_OFFICE_DATA.c_posting_id, OFFICE_CODES.c_office_chn, OFFICE_CODES.c_office_trans, DYNASTIES_1.c_dynasty_chn AS office_dynasty, POSTED_TO_OFFICE_DATA.c_firstyear AS posting_first_year, DYNASTIES_2.c_dynasty_chn AS posting_dynasty, DYNASTIES.c_dynasty_chn AS person_dynasty
FROM (OFFICE_CODES LEFT JOIN DYNASTIES AS DYNASTIES_1 ON OFFICE_CODES.c_dy = DYNASTIES_1.c_dy) INNER JOIN ((BIOG_MAIN LEFT JOIN DYNASTIES ON BIOG_MAIN.c_dy = DYNASTIES.c_dy) INNER JOIN (POSTED_TO_OFFICE_DATA LEFT JOIN DYNASTIES AS DYNASTIES_2 ON POSTED_TO_OFFICE_DATA.c_dy = DYNASTIES_2.c_dy) ON BIOG_MAIN.c_personid = POSTED_TO_OFFICE_DATA.c_personid) ON OFFICE_CODES.c_office_id = POSTED_TO_OFFICE_DATA.c_office_id
WHERE (((DYNASTIES_2.c_dynasty_chn)<>"未詳") AND ((OFFICE_CODES.c_dy)<>[POSTED_TO_OFFICE_DATA].[c_dy]));
